function validate([l, n, k, position, time]) {
  if (!Number.isInteger(l) || l < 1 || l > 100000) return 'l is between 1 and 10^5.';
  if (!Number.isInteger(n) || n < 2 || n > Math.min(l + 1, 50)) return 'n is between 2 and min(l + 1, 50).';
  if (!Number.isInteger(k) || k < 0 || k > Math.min(n - 2, 10)) return 'k is between 0 and min(n - 2, 10).';
  if (position.length !== n || time.length !== n) return 'position and time both need n values.';
  if (position[0] !== 0 || position[n - 1] !== l) return 'position starts at 0 and ends at l.';
  for (let i = 1; i < n; i++) if (!(position[i] > position[i - 1])) return 'position must be strictly increasing.';
  if (time.some(t => !Number.isInteger(t) || t < 1 || t > 100)) return 'Each time is between 1 and 100.';
  if (time.reduce((a, b) => a + b, 0) > 100) return 'The times add up to at most 100.';
  return null;
}

