function minTravelTime(l, n, k, position, time) {
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + time[i];
  }
  // dp[i][used][run]: least time to reach kept sign i after `used` merges, the last `run` of them deleting the signs just before i.
  const dp = Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => new Array(k + 1).fill(Infinity)));
  dp[0][0][0] = 0;
  for (let i = 0; i < n - 1; i++) {
    for (let used = 0; used <= k; used++) {
      for (let run = 0; run <= used; run++) {
        if (dp[i][used][run] === Infinity) {
          continue;
        }
        const rate = prefix[i + 1] - prefix[i - run];
        for (let skip = 0; used + skip <= k && i + 1 + skip < n; skip++) {
          const next = i + 1 + skip;
          const total = dp[i][used][run] + (position[next] - position[i]) * rate;
          dp[next][used + skip][skip] = Math.min(dp[next][used + skip][skip], total);
        }
      }
    }
  }
  return Math.min(...dp[n - 1][k]);
}

