function minTravelTime(l, n, k, position, time) {
  // Apply the merges literally, in every possible order; a state already explored is skipped.
  let best = Infinity;
  const seen = new Set();
  const explore = (pos, tm, left) => {
    const key = `${pos.join(',')}|${tm.join(',')}|${left}`;
    if (seen.has(key)) return;
    seen.add(key);
    if (left === 0) {
      let total = 0;
      for (let i = 0; i + 1 < pos.length; i++) total += (pos[i + 1] - pos[i]) * tm[i];
      best = Math.min(best, total);
      return;
    }
    for (let i = 1; i + 1 < pos.length; i++) {
      const nextTime = tm.slice();
      nextTime[i + 1] += nextTime[i];
      nextTime.splice(i, 1);
      const nextPos = pos.slice();
      nextPos.splice(i, 1);
      explore(nextPos, nextTime, left - 1);
    }
  };
  explore(position, time, k);
  return best;
}

