function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 50 : int(2, 8);
  const l = size === 'large' ? int(1000, 100000) : int(n - 1, 30);
  const k = size === 'large' ? (rand() < 0.7 ? 10 : int(0, 10)) : int(0, Math.min(n - 2, 10));
  // Distinct inner positions between 0 and l, sorted.
  const inner = new Set();
  while (inner.size < n - 2) inner.add(int(1, l - 1));
  const position = [0, ...[...inner].sort((a, b) => a - b), l];
  // Every time is at least 1 and the times add up to at most 100.
  const time = new Array(n).fill(1);
  let extra = int(0, 100 - n);
  if (size === 'small') extra = Math.min(extra, int(0, 6 * n));
  for (; extra > 0; extra--) time[int(0, n - 1)]++;
  return [l, n, k, position, time];
}
